def find_boxes(g,bg):
    H,W=g.shape; boxes=[]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i,j]!=bg and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; col=g[i,j]; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==col and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                boxes.append((col,rs.min(),rs.max(),cs.min(),cs.max(),len(cells)))
    return boxes

