import numpy as np
def solve(g):
    g=[r[:] for r in g]; bg=min(set(x for r in g for x in r))
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                hi,wi=r1-r0-1,c1-c0-1
                fill = 2 if (hi==wi==2) else 7
                for yy in range(r0+1,r1):
                    for xx in range(c0+1,c1):
                        if out[yy][xx]==bg: out[yy][xx]=fill
    return out
