    bg=int(np.min(gi))
    print('---demo',k,'bg',bg)
    for b in comps(gi,bg):
        col,r0,r1,c0,c1=b
        inner=[int(go[r,c]) for r in range(r0+1,r1+1) for c in range(c0+1,c1+1)]
        filled7=sum(x==7 for x in inner); filled2=sum(x==2 for x in inner)
        print(' color',col,'interior shape',(r1-r0-1,c1-c0-1),'fills:{7:%d, 2:%d}'%(filled7,filled2))

