# Re-examine carefully. Collect precise facts across both demos.
import os,re,json,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,bg):
    g=np.array(g); H,W=g.shape; seen=np.zeros((H,W),bool); out=[]
    for i in range(H):
        for j in range(W):
            if g[i,j]!=bg and not seen[i,j]:
                col=g[i,j]; stack=[(i,j)]; seen[i,j]=True; cells=set()
                while stack:
                    y,x=stack.pop(); cells.add((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==col and (ny,nx) not in cells:
                            cells.add((ny,nx)); stack.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                out.append((int(col),min(rs),max(rs),min(cs),max(cs)))
    return out
for k in [1,2]:
    gi=np.array(G[f'Demo pair {k} input']); go=np.array(G[f'Demo pair {k} output'])
    # background = most common color
    vals,_=np.unique(gi,return_counts=True)
    bg=int(vals[np.argmax(return_counts([c for c in vals]))])
    print('---demo',k,'bg',bg)
    boxes=comps(gi,bg)
    info={}
    for b in boxes:
        col,r0,r1,c0,c1=b
        hi,wi=r1-r0-1,c1-c0-1
        inter=[int(go[r,c]) for r in range(r0+1,r1+1) for c in range(c0+1,c1+1)]
        info.setdefault(hi,{}).setdefault(wi,{})
        for x in set(inter): info[hi][wi][x]+=1
        if 0<=r1-r0-1 and 0<=c1-c0-1:
            print(f'  box color={col} bbox=rows{r0}-{r1} cols{c0}-{c1} interior={hi}x{wi} -> {dict(info.get((hi,wi),{}))}')
    # any boxes with zero interior?
    for b in boxes:
        col,r0,r1,c0,c1=b
        if r0==r1 or c0==c1: print(f'  degenerate box color={col} bbox rows{r0}-{r1} cols{c0}-{c1}')

