                            cells.add((ny,nx)); stack.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                out.append((int(col),min(rs),max(rs),min(cs),max(cs)))
    return out
for k in [1,2]:
    gi=G[f'Demo pair {k} input']; go=G[f'Demo pair {k} output']
    v,_=np.unique(np.array(gi),return_counts=True)
    bg=int(v[np.argmax([int(x) for x in v])].data[0])
    print('---demo',k,'bg',bg)
    for b in comps(np.array(gi),bg):
        col,r0,r1,c0,c1=b
        inter=[[int(go[r,c]) for c in range(c0+1,c1+1)] for r in range(r0+1,r1+1)]
        fills={}
        for row in inter:
            for x in row: fills[x]=fills.get(x,0)+1
        interior=(r1-r0-1)*(c1-c0-1)
